-- New site onboarding request (slug: site-onboarding), audience LINK-ONLY.
--
-- Collects what is needed to create a site in `locations` and `pricing_simple`
-- from the RM or RD who knows it, and routes it to one approver who makes the
-- entries by hand.
--
-- IT WRITES TO NEITHER TABLE, deliberately. A submission is a request, not a
-- migration: `location_code` is a load-bearing customer URL (CLAUDE.md
-- constraint #1) and the package slugs are inconsistent enough across the estate
-- -- 38 distinct values, ext_* beside fs_* beside "Express" and "express" --
-- that picking one is a judgement. The approver uses sysadmin's Add Location,
-- which inserts `locations` FIRST and rolls back cleanly on failure.
--
-- THE SYNC RUNS locations -> pricing_simple, NOT THE REVERSE.
-- trg_sync_pricing_simple fires AFTER UPDATE ON locations. Nothing propagates
-- upward, so creating pricing_simple rows alone leaves `locations` without the
-- site and the trigger with nothing to fire on.
--
-- NOT ASKED FOR, on purpose: location_code. It is the customer-facing slug in
-- /signup/{code}, it can never change once bookmarked, and it is the approver's
-- call rather than the requester's.
--
-- ASKED FOR THOUGH NOT REQUESTED: rm_email and am_email. A name is not access --
-- trg_sync_user_permissions keys off the ADDRESS, so a site created with names
-- alone is a site its own RM cannot open.
--
-- Generated by scripts/gen-site-onboarding.ts, the source of truth.
-- Status: APPLIED to the live project (rewokyofschtvqgxrxwl) on 2026-10-01.
--
-- SAFE TO RE-RUN: upserts the form by slug and overwrites the draft's schema.
-- The form is created as a DRAFT. Publishing it in the builder is what mints
-- the /forms/site-onboarding link.

insert into public.forms
  (slug, title, description, audience, status, notify_webhook,
   turnstile_required, success_message, created_by, last_edited_by)
values
  ('site-onboarding',
   'New site onboarding',
   'What we need to set a new site up in pricing. Takes a couple of minutes; the pricing team does the rest.',
   'link-only',
   'draft',
   true,
   -- Turnstile is for public audiences. This link goes to named managers, and a
   -- captcha in front of them is friction without a threat model.
   false,
   'Thanks -- that is with the pricing team. You will hear back if anything is unclear.',
   'f42882fd-ee5a-433e-b10b-713d5dff8a89',
   'f42882fd-ee5a-433e-b10b-713d5dff8a89')
on conflict (slug) do update
  set title = excluded.title,
      description = excluded.description,
      audience = excluded.audience,
      turnstile_required = excluded.turnstile_required,
      success_message = excluded.success_message,
      last_edited_at = now();

-- Draft version: insert on first run, overwrite its schema on later ones.
with f as (select id, draft_version_id from public.forms where slug = 'site-onboarding'),
ins as (
  -- Columns verified against the live table rather than assumed: form_versions
  -- has is_draft (boolean) and no creator column. A first guess at `status` and
  -- `created_by` failed, and --single-transaction rolled the forms insert back
  -- with it rather than leaving a form with no version.
  insert into public.form_versions (form_id, version_number, is_draft, schema)
  select f.id, 1, true, '{"fields":[{"key":"sec_site","id":"928de58f","type":"heading","label":"The site","text":"The site","level":"h3","required":false},{"key":"location_name","id":"33f724ca","type":"short_text","label":"Location name","required":true,"maxLength":200,"helpText":"How the site is referred to in conversation, e.g. Binghamton. Not the web address."},{"key":"site_number","id":"eff3f96f","type":"short_text","label":"Site number","required":true,"maxLength":3,"helpText":"Three digits, zero-padded. 069, not 69."},{"key":"street_address","id":"3e4389d4","type":"long_text","label":"Street address","required":true,"maxLength":300,"helpText":"Full postal address, as it should appear on paperwork."},{"key":"site_email","id":"1a5c22f2","type":"email","label":"Site email","required":true,"helpText":"The address the site itself reads. Customer replies and site copies go here."},{"key":"sec_people","id":"6d667d09","type":"heading","label":"Who runs it","text":"Who runs it","level":"h3","required":false},{"key":"rm_name","id":"399d6967","type":"short_text","label":"Regional Manager name","required":true,"maxLength":200},{"key":"rm_email","id":"d9c2bb58","type":"email","label":"Regional Manager email","required":true,"helpText":"This is what grants them access to the site. A name alone does not."},{"key":"am_name","id":"a000c59c","type":"short_text","label":"Regional Director / Area Manager name","required":true,"maxLength":200},{"key":"am_email","id":"6f344263","type":"email","label":"Regional Director / Area Manager email","required":true,"helpText":"Same again: the address is what grants access."},{"key":"sec_packages","id":"324baaf0","type":"heading","label":"Packages","text":"Packages","level":"h3","required":false},{"key":"site_type","id":"f0ef9088","type":"radio","label":"Site type","required":true,"layout":"inline","options":[{"label":"Exterior only","value":"exterior"},{"label":"Full service","value":"full_service"},{"label":"Both","value":"both"}]},{"key":"packages","id":"01105d6b","type":"long_text","label":"Unlimited packages offered","required":true,"maxLength":2000,"helpText":"One package per line, in the form:  name | single wash price | monthly unlimited price. Example:  Bubble Bath | 25.00 | 49.00. Only packages that offer an unlimited plan."},{"key":"notes","id":"0fd39150","type":"long_text","label":"Anything else we should know","required":false,"maxLength":2000,"helpText":"Opening date, pricing that differs from the rest of the region, anything unusual."}],"workflow":{"default_stage":"review","stages":[{"id":"review","label":"Pricing setup","kind":"approval","approver_source":{"type":"static_emails","emails":["josh.copp@splashcarwashes.com"]},"transitions":[{"to":"entered","label":"Entered in pricing","requires":{"typed_name":true}},{"to":"needs_info","label":"Need more detail","requires":{"note":true}}]},{"id":"entered","label":"Entered in pricing","kind":"outcome","tint":"success","transitions":[]},{"id":"needs_info","label":"Need more detail","kind":"outcome","tint":"warning","transitions":[]}]}}'::jsonb
    from f where f.draft_version_id is null
  returning id, form_id
)
update public.forms set draft_version_id = ins.id, last_edited_at = now()
  from ins where public.forms.id = ins.form_id;

update public.form_versions v
   set schema = '{"fields":[{"key":"sec_site","id":"928de58f","type":"heading","label":"The site","text":"The site","level":"h3","required":false},{"key":"location_name","id":"33f724ca","type":"short_text","label":"Location name","required":true,"maxLength":200,"helpText":"How the site is referred to in conversation, e.g. Binghamton. Not the web address."},{"key":"site_number","id":"eff3f96f","type":"short_text","label":"Site number","required":true,"maxLength":3,"helpText":"Three digits, zero-padded. 069, not 69."},{"key":"street_address","id":"3e4389d4","type":"long_text","label":"Street address","required":true,"maxLength":300,"helpText":"Full postal address, as it should appear on paperwork."},{"key":"site_email","id":"1a5c22f2","type":"email","label":"Site email","required":true,"helpText":"The address the site itself reads. Customer replies and site copies go here."},{"key":"sec_people","id":"6d667d09","type":"heading","label":"Who runs it","text":"Who runs it","level":"h3","required":false},{"key":"rm_name","id":"399d6967","type":"short_text","label":"Regional Manager name","required":true,"maxLength":200},{"key":"rm_email","id":"d9c2bb58","type":"email","label":"Regional Manager email","required":true,"helpText":"This is what grants them access to the site. A name alone does not."},{"key":"am_name","id":"a000c59c","type":"short_text","label":"Regional Director / Area Manager name","required":true,"maxLength":200},{"key":"am_email","id":"6f344263","type":"email","label":"Regional Director / Area Manager email","required":true,"helpText":"Same again: the address is what grants access."},{"key":"sec_packages","id":"324baaf0","type":"heading","label":"Packages","text":"Packages","level":"h3","required":false},{"key":"site_type","id":"f0ef9088","type":"radio","label":"Site type","required":true,"layout":"inline","options":[{"label":"Exterior only","value":"exterior"},{"label":"Full service","value":"full_service"},{"label":"Both","value":"both"}]},{"key":"packages","id":"01105d6b","type":"long_text","label":"Unlimited packages offered","required":true,"maxLength":2000,"helpText":"One package per line, in the form:  name | single wash price | monthly unlimited price. Example:  Bubble Bath | 25.00 | 49.00. Only packages that offer an unlimited plan."},{"key":"notes","id":"0fd39150","type":"long_text","label":"Anything else we should know","required":false,"maxLength":2000,"helpText":"Opening date, pricing that differs from the rest of the region, anything unusual."}],"workflow":{"default_stage":"review","stages":[{"id":"review","label":"Pricing setup","kind":"approval","approver_source":{"type":"static_emails","emails":["josh.copp@splashcarwashes.com"]},"transitions":[{"to":"entered","label":"Entered in pricing","requires":{"typed_name":true}},{"to":"needs_info","label":"Need more detail","requires":{"note":true}}]},{"id":"entered","label":"Entered in pricing","kind":"outcome","tint":"success","transitions":[]},{"id":"needs_info","label":"Need more detail","kind":"outcome","tint":"warning","transitions":[]}]}}'::jsonb
  from public.forms f
 where f.slug = 'site-onboarding' and v.id = f.draft_version_id;

select f.slug, f.audience, f.status, f.turnstile_required,
       jsonb_array_length(v.schema->'fields') as fields,
       jsonb_array_length(v.schema->'workflow'->'stages') as stages,
       v.schema->'workflow'->'stages'->0->'approver_source'->'emails'->>0 as approver
  from public.forms f
  join public.form_versions v on v.id = f.draft_version_id
 where f.slug = 'site-onboarding';
